inline ::flatbuffers::Offset<EPM> CreateEPM(::flatbuffers::FlatBufferBuilder &_fbb, const EPMT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return EPM::Pack(_fbb, _o, _rehasher);
}

