  auto _HONORIFIC_SUFFIX = _o->HONORIFIC_SUFFIX.empty() ? 0 : _fbb.CreateString(_o->HONORIFIC_SUFFIX);
  auto _JOB_TITLE = _o->JOB_TITLE.empty() ? 0 : _fbb.CreateString(_o->JOB_TITLE);
  auto _OCCUPATION = _o->OCCUPATION.empty() ? 0 : _fbb.CreateString(_o->OCCUPATION);
  auto _ADDRESS = _o->ADDRESS ? CreateAddress(_fbb, _o->ADDRESS.get(), _rehasher) : 0;
  auto _ALTERNATE_NAMES = _o->ALTERNATE_NAMES.size() ? _fbb.CreateVectorOfStrings(_o->ALTERNATE_NAMES) : 0;
  auto _EMAIL = _o->EMAIL.empty() ? 0 : _fbb.CreateString(_o->EMAIL);
  auto _TELEPHONE = _o->TELEPHONE.empty() ? 0 : _fbb.CreateString(_o->TELEPHONE);
  auto _KEYS = _o->KEYS.size() ? _fbb.CreateVector<::flatbuffers::Offset<CryptoKey>> (_o->KEYS.size(), [](size_t i, _VectorArgs *__va) { return CreateCryptoKey(*__va->__fbb, __va->__o->KEYS[i].get(), __va->__rehasher); }, &_va ) : 0;
  auto _MULTIFORMAT_ADDRESS = _o->MULTIFORMAT_ADDRESS.size() ? _fbb.CreateVectorOfStrings(_o->MULTIFORMAT_ADDRESS) : 0;
  auto _SIGNATURE = _o->SIGNATURE.empty() ? 0 : _fbb.CreateString(_o->SIGNATURE);
  auto _SIGNATURE_TIMESTAMP = _o->SIGNATURE_TIMESTAMP;
  auto _CHAIN_PROOFS = _o->CHAIN_PROOFS.size() ? _fbb.CreateVector<::flatbuffers::Offset<ChainProof>> (_o->CHAIN_PROOFS.size(), [](size_t i, _VectorArgs *__va) { return CreateChainProof(*__va->__fbb, __va->__o->CHAIN_PROOFS[i].get(), __va->__rehasher); }, &_va ) : 0;
  auto _ENTITY_TYPE = _o->ENTITY_TYPE;
  auto _SIGNATURE_ALGORITHM = _o->SIGNATURE_ALGORITHM.empty() ? 0 : _fbb.CreateString(_o->SIGNATURE_ALGORITHM);
  auto _DOMAIN_PROOFS = _o->DOMAIN_PROOFS.size() ? _fbb.CreateVector<::flatbuffers::Offset<DomainProof>> (_o->DOMAIN_PROOFS.size(), [](size_t i, _VectorArgs *__va) { return CreateDomainProof(*__va->__fbb, __va->__o->DOMAIN_PROOFS[i].get(), __va->__rehasher); }, &_va ) : 0;
